function KanbanCardMenu({ className }: { className?: string }) {
  const item = useKanbanCard()
  const { canDrop: canMoveTo, columns, items, moveFromMenu } = useKanban()
  const siblings = getColumnItems(items, item.column)
  const index = siblings.findIndex((sibling) => sibling.id === item.id)
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            aria-label={`Move ${item.title}`}
            className={className}
            size='icon-xs'
            variant='ghost'
          />
        }
      >
        <IconPlaceholder
          lucide='EllipsisIcon'
          tabler='IconDots'
          hugeicons='MoreHorizontalCircle01Icon'
          phosphor='DotsThreeOutlineIcon'
          remixicon='RiMoreLine'
        />
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-auto min-w-44'>
        <DropdownMenuGroup>
          <DropdownMenuLabel>Move to</DropdownMenuLabel>
          {columns
            .filter((column) => column.id !== item.column)
            .map((column) => {
              const full = !canMoveTo(item.id, column.id)
              return (
                <DropdownMenuItem
                  key={column.id}
                  disabled={full}
                  onClick={() => moveFromMenu(item.id, column.id, 0)}
                >
                  {column.title}
                  {full && (
                    <span className='text-muted-foreground ml-auto pl-4 text-xs'>
                      Full
                    </span>
                  )}
                </DropdownMenuItem>
              )
            })}
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          disabled={index <= 0}
          onClick={() => moveFromMenu(item.id, item.column, index - 1)}
        >
          Move up
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={index === siblings.length - 1}
          onClick={() => moveFromMenu(item.id, item.column, index + 1)}
        >
          Move down
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

